import { useContext, useEffect, useState } from 'react';
import { Box, Grid, Typography } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import CustomAppBar from '../../components/shared-components/AppBar/AppBar';
import { SettingsContext } from '../../context/SettingsContext';
import Footer from '../../components/shared-components/Footer';
import WeatherWidget from '../../components/dashboard-components/WeatherWidget';
import ServerInfoWidget from '../../components/dashboard-components/ServerInfoWidget';
import ServerInfoLineChart from '../../components/dashboard-components/ServerInfoLineChart';
import DashboardService from '../../services/DashboardService';
import { useUser } from '../../context/UserContext';

const Dashboard = () => {
  const { language, themeMode} = useContext(SettingsContext);
  const theme = useTheme();
  const { userState } = useUser();
  const [todayData, setTodayData] = useState(null);
  const [yesterdayData, setYesterdayData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [refreshingNow, setRefreshingNow] = useState(false);
  const [chartData, setChartData] = useState([]);
  const [maxApiCount7, setMaxApiCount7] = useState(0);
  const [chartRangeDays, setChartRangeDays] = useState(7); // 7 | 14 | 30
  const [yesterdayPickerDate, setYesterdayPickerDate] = useState('');
  const [isYesterdayFromDatePicker, setIsYesterdayFromDatePicker] = useState(false);

  const formatDateForTitle = (dateString) => {
    if (!dateString) return 'Yesterday';
    const d = new Date(dateString);
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const formatted = language === 'cn' ? `${year}/${month}/${day}` : `${day}/${month}/${year}`;
    const prefix = language === 'cn' ? 'Date ' : 'Date ';
    return `${prefix}`;
    // return `${prefix}${formatted}`;
  };

  // 处理API返回的数据格式
  const processLogData = (data) => {
    if (!data) return null;
    
    return {
      cpuUsage: data.cpuUsage || 0,
      memoryUsage: data.memoryUsage || 0,
      memoryFree: data.memoryFree || 0,
      memoryAvailable: data.memoryAvailable || 0,
      diskUsage: data.diskUsage || 0,
      diskFree: data.diskFree || 0,
      apiCount: data.apiCount || 0,
      anonymousCount: data.anonymousCount || 0,
      blogCount: data.blogCount || 0,
      chatbotCount: data.chatbotCount || 0,
      myIpCount: data.myIPCount || 0,
      reportDate: data.reportDate || null
    };
  };

  // 重新获取now数据
  const refreshNowData = async () => {
    if (!userState.access) return;
    
    try {
      setRefreshingNow(true);
      const response = await DashboardService.getLogNow(userState.access);
      setTodayData(processLogData(response));
    } catch (error) {
      console.error('Failed to refresh now data:', error);
    } finally {
      setRefreshingNow(false);
    }
  };

  useEffect(() => {
    const fetchData = async () => {
      if (!userState.access) {
        setLoading(false);
        return;
      }

      try {
        setLoading(true);
        
        // 获取近 (chartRangeDays + 2) 天的日志（AET 基准）：AET+1 天 到 AET-(chartRangeDays) 天；后续再截取最新 chartRangeDays 天
        const now = new Date();
        const sydneyTime = new Date(now.toLocaleString('en-US', { timeZone: 'Australia/Sydney' }));
        const endDate = new Date(sydneyTime);
        endDate.setDate(endDate.getDate() + 1);
        const startDate = new Date(sydneyTime);
        startDate.setDate(startDate.getDate() - chartRangeDays);

        const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
        const params = {
          startDate: fmt(startDate),
          endDate: fmt(endDate),
          sortBy: 'reportdate',
          sortOrder: 'asc'
        };

        // 并行获取今日与区间日志
        const [todayResponse, logs] = await Promise.all([
          DashboardService.getLogNow(userState.access),
          DashboardService.getLogsWithFilter(params, userState.access)
        ]);

        const list = logs?.data || [];
        setTodayData(processLogData(todayResponse));
        // 按日期排序，取最后一条作为“昨日”（考虑时差与端点包含性）
        const sortedByDate = list
          .filter((x) => x && x.reportDate)
          .sort((a, b) => new Date(a.reportDate) - new Date(b.reportDate));
        const latest = sortedByDate.length > 0 ? sortedByDate[sortedByDate.length - 1] : null;
        setYesterdayData(processLogData(latest));
        setYesterdayPickerDate(latest?.reportDate ? new Date(latest.reportDate).toISOString().slice(0,10) : '');
        setIsYesterdayFromDatePicker(false);

        // 规范化数据：在近 N+2 天中截取最新 N 天；x 轴为 MM-DD
        const lastN = sortedByDate.slice(-chartRangeDays);
        const normalized = lastN.map((x) => ({
          date: x.reportDate ? new Date(x.reportDate).toISOString().slice(5, 10) : '',
          memoryUsage: x.memoryUsage ?? 0,
          memoryAvailable: x.memoryAvailable ?? 0,
          apiCount: x.apiCount ?? 0,
          anonymousCount: x.anonymousCount ?? 0,
          chatbotCount: x.chatbotCount ?? 0,
          blogCount: x.blogCount ?? 0,
          myIpCount: x.myIPCount ?? 0,
        }));
        setChartData(normalized);
        // 仍然用最近 7 天计算 max，以保持 API Widget 的参考一致
        const last7ForMax = sortedByDate.slice(-7).map((x) => x.apiCount ?? 0);
        const maxApi = last7ForMax.reduce((max, v) => Math.max(max, v), 0);
        setMaxApiCount7(maxApi);
      } catch (error) {
        console.error('Failed to fetch dashboard data:', error);
        // 如果API调用失败，使用默认数据
        setTodayData({
          cpuUsage: 0,
          memoryUsage: 0,
          memoryFree: 0,
          memoryAvailable: 0,
          diskUsage: 0,
          diskFree: 0,
          apiCount: 0,
          anonymousCount: 0,
          blogCount: 0,
          chatbotCount: 0,
          myIpCount: 0,
          reportDate: null
        });
        setYesterdayData({
          cpuUsage: 0,
          memoryUsage: 0,
          memoryFree: 0,
          memoryAvailable: 0,
          diskUsage: 0,
          diskFree: 0,
          apiCount: 0,
          anonymousCount: 0,
          blogCount: 0,
          chatbotCount: 0,
          myIpCount: 0,
          reportDate: null
        });
        setChartData([]);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [userState.access, chartRangeDays]);

  return (
    <Box
      sx={{
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      <CustomAppBar />
      
      {/* 主要内容区域 */}
      <Box
        sx={{
          flex: 1,
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'center',
          mt: 12,
          px: 2,
        }}
      >
        {/* Server Info Widgets */}
        <Box sx={{ mb: 4 }}>
          <Grid 
            container 
            spacing={{ xs: 2, md: 4 }} 
            justifyContent="center"
            direction={{ xs: 'column', md: 'row' }}
            alignItems="center"
          >
            <Grid item>
              <ServerInfoWidget 
                title="Now" 
                data={todayData}
                loading={loading || refreshingNow}
                onRefresh={refreshNowData}
                sx={{ 
                  boxShadow: 3
                }}
                apiMax7={maxApiCount7}
              />
            </Grid>
            <Grid item>
              <ServerInfoWidget 
                title={isYesterdayFromDatePicker ? formatDateForTitle(yesterdayPickerDate) : 'Yesterday'} 
                data={yesterdayData}
                loading={loading}
                sx={{ 
                  boxShadow: 3
                }}
                apiMax7={maxApiCount7}
                datePickerEnabled
                selectedDate={yesterdayPickerDate}
                onDateChange={async (v)=>{
                  if (!userState.access || !v) return;
                  try{
                    const data = await DashboardService.getLogByDate(v, userState.access);
                    setYesterdayData(processLogData(data));
                    setYesterdayPickerDate(v);
                    setIsYesterdayFromDatePicker(true);
                  }catch(err){
                    console.error('Failed to get log by date', err);
                  }
                }}
              />
            </Grid>
          </Grid>
        </Box>

        {/* 近7天折线图 - Mobile: 1x4, Desktop: 2x2 */}
        <Box sx={{ width: '100%', maxWidth: "1120px" }}>
          <Grid container spacing={2} columns={{ xs: 1, md: 2 }}>
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="Memory Usage"
                data={chartData.map(d => ({
                  ...d,
                  memoryPercent: (d.memoryUsage + d.memoryAvailable) > 0
                    ? Math.round((d.memoryUsage / (d.memoryUsage + d.memoryAvailable)) * 100)
                    : 0
                }))}
                dataKey="memoryPercent"
                color="#ef5350"
                yAxisTickFormatter={(v) => `${v}%`}
                tooltipFormatter={(value) => [`${value}%`, 'Memory Usage']}
                loading={loading}
                rangeDays={chartRangeDays}
                onRangeChange={setChartRangeDays}
                IconComponent={require('@mui/icons-material').Memory}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="Chatbot Calls"
                data={chartData}
                dataKey="chatbotCount"
                color="#ff7300"
                loading={loading}
                tooltipFormatter={(value) => [String(value), 'Chatbot Calls']}
                rangeDays={chartRangeDays}
                onRangeChange={setChartRangeDays}
                IconComponent={require('@mui/icons-material').SmartToy}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="API Calls"
                data={chartData}
                dataKey="apiCount"
                color={theme.palette.warning.main}
                loading={loading}
                tooltipFormatter={(value) => [String(value), 'API Calls']}
                rangeDays={chartRangeDays}
                onRangeChange={setChartRangeDays}
                IconComponent={require('@mui/icons-material').Api}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="Anonymous Calls"
                data={chartData}
                dataKey="anonymousCount"
                color={theme.palette.success.main}
                loading={loading}
                tooltipFormatter={(value) => [String(value), 'Anonymous Calls']}
                rangeDays={chartRangeDays}
                onRangeChange={setChartRangeDays}
                IconComponent={require('@mui/icons-material').Person}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="Blog Calls"
                data={chartData}
                dataKey="blogCount"
                color="#42a5f5"
                loading={loading}
                tooltipFormatter={(value) => [String(value), 'Blog Calls']}
                rangeDays={chartRangeDays}
                onRangeChange={setChartRangeDays}
                IconComponent={require('@mui/icons-material').Article}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="My Calls"
                data={chartData}
                dataKey="myIpCount"
                color="#9f86c0"
                loading={loading}
                tooltipFormatter={(value) => [String(value), 'My Calls']}
                rangeDays={chartRangeDays}
                onRangeChange={setChartRangeDays}
                IconComponent={require('@mui/icons-material').LocationOn}
              />
            </Grid>
          </Grid>
        </Box>

        {/* <Box sx={{ mt: 8 }}>
          <WeatherWidget sx={{ width: "400px", height: "400px" }}/>
        </Box> */}
      </Box>

      {/* 下部 Footer */}
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'center',
          backgroundColor: 'background.default',
          borderTop: (theme) => ({
            xs: 'none',
            md: `1px solid ${theme.palette.divider}`,
          }),
          maxWidth: (theme) => theme.breakpoints.values.lg, 
          width: '100%', 
          mx: 'auto',
        }}
      >
        <Footer />
      </Box>

      
    </Box>
  );
};

export default Dashboard;
